 AND ValueColumn = N'Guid' AND DefaultSortColumnName = N'ListName' AND IsDefaultColumn = N'0' AND DetailPageUrl = N'ProductDetail' AND IsDetailWindowed = 1
 AND EntityTypeId = 51 AND InformationPageUrl = N'' AND GroupColumn = N'' AND ColourHexColumn = N'#000000' AND ExternalSearchPageUrl = N''
UPDATE SUserInterface.DropDownListDefinitions SET RowStatus = 1, Guid = '7da1444e-4407-4c3b-8469-14851a5ed0fa', Code = N'JOB TYPE - QUOTES', NameColumn = N'Name', ValueColumn = N'Guid', SqlQuery = N'SELECT
    root_hobt.Name,
    root_hobt.Guid
FROM SJob.JobTypes root_hobt
JOIN SCore.OrganisationalUnits AS ORG
    ON ORG.ID = root_hobt.OrganisationalUnitID
JOIN SSop.Quotes AS Q
    ON Q.OrganisationalUnitID = ORG.ID
LEFT JOIN SSop.EnquiryServices AS ES
    ON ES.ID = Q.EnquiryServiceID
WHERE
        (root_hobt.Guid = root_hobt.Guid)
    AND (Q.Guid = [[RecordGuid]])
    AND
    (
        NOT EXISTS
        (
            SELECT 1
            FROM SSop.QuoteItems AS QI
            WHERE QI.QuoteId = Q.ID
              AND QI.RowStatus NOT IN (0,254)
        )
        OR root_hobt.ID =
        (
            SELECT TOP (1)
                EffectiveJobType.JobTypeId
            FROM
            (
                SELECT
                    1 AS PriorityOrder,
                    NULLIF(NULLIF(Q.JobTypeId, 0), -1) AS JobTypeId

                UNION ALL

                SELECT
                    2 AS PriorityOrder,
                    NULLIF(NULLIF(ES.JobTypeId, 0), -1) AS JobTypeId

                UNION ALL

                SELECT
                    3 AS PriorityOrder,
                    NULLIF(NULLIF(P.CreatedJobType, 0), -1) AS JobTypeId
                FROM SSop.QuoteItems AS QI2
                JOIN SProd.Products AS P
                    ON P.ID = QI2.ProductId
                   AND P.RowStatus NOT IN (0,254)
                WHERE QI2.QuoteId = Q.ID
                  AND QI2.RowStatus NOT IN (0,254)
                  AND ISNULL(P.CreatedJobType, -1) <> -1
            ) AS EffectiveJobType
            WHERE EffectiveJobType.JobTypeId IS NOT NULL
            ORDER BY
                EffectiveJobType.PriorityOrder,
                EffectiveJobType.JobTypeId
        )
    )', DefaultSortColumnName = N'Name', IsDefaultColumn = N'0', DetailPageUrl = N'', IsDetailWindowed = 0, EntityTypeId = 41, InformationPageUrl = N'', GroupColumn = N'', ColourHexColumn = N'#000000', ExternalSearchPageUrl = N'' WHERE ID = 93 AND RowStatus = 1 AND Guid = '7da1444e-4407-4c3b-8469-14851a5ed0fa' AND Code = N'JOB TYPE - QUOTES' AND NameColumn = N'Name'
 AND ValueColumn = N'Guid' AND DefaultSortColumnName = N'Name' AND IsDefaultColumn = N'0' AND DetailPageUrl = N'' AND IsDetailWindowed = 0
 AND EntityTypeId = 41 AND InformationPageUrl = N'' AND GroupColumn = N'' AND ColourHexColumn = N'#000000' AND ExternalSearchPageUrl = N''
