SELECT root_hobt.Name, root_hobt.Guid
FROM SFin.InvoiceSchedules AS root_hobt
JOIN SFin.InvoiceScheduleTrigger AS It ON (It.ID = root_hobt.TriggerId)
JOIN SSop.Quotes AS q ON (q.ID = root_hobt.QuoteId)
WHERE 
		(q.Guid = [[ParentGuid]])
	AND (root_hobt.RowStatus NOT IN (0,254))', DefaultSortColumnName = N'Name', IsDefaultColumn = N'0', DetailPageUrl = N'DynamicEdit', IsDetailWindowed = 0, EntityTypeId = 200, InformationPageUrl = N'InvoicingScheduleDetail', GroupColumn = N'', ColourHexColumn = N'', ExternalSearchPageUrl = N'' WHERE ID = 104 AND RowStatus = 1 AND Guid = '4677922f-9013-403b-949a-29605fd72671' AND Code = N'QUOTEITEMSINVOICINGS' AND NameColumn = N'Name'
 AND ValueColumn = N'Guid' AND DefaultSortColumnName = N'Name' AND IsDefaultColumn = N'0' AND DetailPageUrl = N'DynamicEdit' AND IsDetailWindowed = 0
