INSERT SUserInterface.DropDownListDefinitions(ID, RowStatus, Guid, Code, NameColumn, ValueColumn, SqlQuery, DefaultSortColumnName, IsDefaultColumn, DetailPageUrl, IsDetailWindowed, EntityTypeId, InformationPageUrl, GroupColumn, ColourHexColumn, ExternalSearchPageUrl) VALUES (117, 1, '2b02dcd9-c8d5-43cc-bab9-8a772704a616', N'GETCUSTOMRIBASTAGES', N'Name', N'Value', N'SELECT
    RS.Description AS Name,
    RS.Guid AS Value
FROM SJob.FeeAmendment root_hobt
JOIN SJob.Jobs J
    ON J.ID = root_hobt.JobID
JOIN SJob.JobRibaStageFees JRSF
    ON JRSF.JobID = J.ID
JOIN SJob.RibaStages RS
    ON RS.ID = JRSF.RibaStageID
WHERE J.Guid = [[ParentGuid]]
  AND RS.IsCustomStage = 1
  AND RS.RowStatus NOT IN (0,254)
  AND JRSF.RowStatus NOT IN (0,254)', N'Value', N'0', N'', 0, 70, N'', N'', N'', N'')
IF NOT EXISTS (SELECT ID, RowStatus, Guid, Code, NameColumn, ValueColumn, SqlQuery, DefaultSortColumnName, IsDefaultColumn, DetailPageUrl, IsDetailWindowed, EntityTypeId, InformationPageUrl, GroupColumn, ColourHexColumn, ExternalSearchPageUrl FROM SUserInterface.DropDownListDefinitions WITH (NOLOCK) WHERE ID = 118)
INSERT SUserInterface.DropDownListDefinitions(ID, RowStatus, Guid, Code, NameColumn, ValueColumn, SqlQuery, DefaultSortColumnName, IsDefaultColumn, DetailPageUrl, IsDetailWindowed, EntityTypeId, InformationPageUrl, GroupColumn, ColourHexColumn, ExternalSearchPageUrl) VALUES (118, 1, '5adfeb8c-7e5a-49a5-b648-3d2de1409378', N'QUOTEJOBTYPES', N'ListName', N'Guid', N'SELECT TOP(10)
    root_hobt.ListName,
    root_hobt.Guid
FROM SProd.tvf_Products(1) root_hobt
WHERE
    (
        root_hobt.CreatedJobType = -1
        OR EXISTS
        (
            SELECT 1
            FROM SSop.Quotes AS q
            LEFT JOIN SSop.EnquiryServices AS es
                ON es.ID = q.EnquiryServiceID
            WHERE q.Guid = ''[[ParentGuid]]''
              AND root_hobt.CreatedJobType =
                  COALESCE
                  (
                      NULLIF(NULLIF(q.JobTypeId, 0), -1),
                      NULLIF(NULLIF(es.JobTypeId, 0), -1),
                      (
                          SELECT MIN(NULLIF(NULLIF(p.CreatedJobType, 0), -1))
                          FROM SSop.QuoteItems AS qi
                          JOIN SProd.Products AS p
                              ON p.ID = qi.ProductId
                             AND p.RowStatus NOT IN (0,254)
                          WHERE qi.QuoteId = q.ID
                            AND qi.RowStatus NOT IN (0,254)
                            AND ISNULL(p.CreatedJobType, -1) <> -1
                      )
                  )
        )
    )', N'', N'0', N'', 0, 41, N'', N'', N'', N'')
